    deepExplanation: "Example:\n\n```ts\nimport { useDeferredValue, useMemo, useState } from \"react\";\n\nexport function Search({ items }: { items: string[] }) {\n  const [query, setQuery] = useState(\"\");\n  const deferredQuery = useDeferredValue(query);\n\n  const filtered = useMemo(\n    () => items.filter(item => item.toLowerCase().includes(deferredQuery.toLowerCase())),\n    [items, deferredQuery],\n  );\n\n  return (\n    <>\n      <label>\n        Search\n        <input value={query} onChange={event => setQuery(event.target.value)} />\n      </label>\n      <p>{filtered.length} results</p>\n    </>\n  );\n}\n```\n\nWhy it matters: It affects correctness, responsiveness, maintainability or scalability. Senior interviews expect trade-off analysis, not API memorization. Enterprise systems require observability, testing, accessibility and safe migration paths.",
